        top: 10,
        right: 10,
        bottom: 30,
        left: 10
      };
      const svg = container.append("svg").attr("width", "100%").attr("height", "100%").attr("viewBox", `0 0 ${width} ${height}`);
      const x = d3.scaleLinear().domain([0, lineData.value.length - 1]).range([margin.left, width - margin.right]);
