      if (valueArray.length > 0) {
        const items = valueArray.map(item => {
          if (typeof item === "object" && item !== null) {
            let text = item.raw || item.value || JSON.stringify(item);
            if (item.unit) text += ` ${item.unit}`;
            if (item.year) text += ` (${item.year})`;
