    });
    const hasData = computed(() => {
      if (!processedField.value) return false;
      if (Array.isArray(processedField.value)) return processedField.value.length > 0;
      if (typeof processedField.value === "object") return Object.keys(processedField.value).length > 0;
      return String(processedField.value).trim().length > 0;
    });
    return {
      hoveredIndex,
      activeIndex,
      isTextHovered,
      pieContainer,
      barContainer,
      lineContainer,
      stackedContainer,
      handleTextHover,
      resetHover,
      handleTextClick,
      formatSimpleText,
      hasData,
      isValidPieData,
      pieData,
      simpleBarData,
      lineData,
      formatNumber,
      processedField
